<?php

declare(strict_types=1);

namespace App\Modules\Desktop\Models;

use App\Modules\Desktop\Data\ReleaseChannel;
use App\Modules\Desktop\Data\ReleasePlatform;
use App\Support\Models\HasPublicId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Support\Carbon;

/**
 * @property int $id
 * @property string $public_id
 * @property ReleaseChannel $channel
 * @property ReleasePlatform $platform
 * @property string $arch
 * @property string $version
 * @property string $path on the private disk, generated by SprintSync
 * @property string $extension
 * @property int $size_bytes
 * @property string $sha256
 * @property string|null $min_os
 * @property bool $signed
 * @property bool $active
 * @property Carbon $released_at
 */
final class DesktopRelease extends Model
{
    use HasPublicId;

    protected $guarded = ['id', 'public_id'];

    protected $hidden = ['path'];

    protected function casts(): array
    {
        return [
            'channel' => ReleaseChannel::class,
            'platform' => ReleasePlatform::class,
            'size_bytes' => 'integer',
            'signed' => 'boolean',
            'active' => 'boolean',
            'released_at' => 'datetime',
        ];
    }

    public static function latest(ReleaseChannel $channel, ReleasePlatform $platform, string $arch): ?self
    {
        return self::query()
            ->where('channel', $channel)
            ->where('platform', $platform)
            ->where('arch', $arch)
            ->where('active', true)
            ->orderByDesc('released_at')
            ->orderByDesc('id')
            ->first();
    }

    /**
     * The newest build per platform and architecture. With several channels,
     * the first channel listed wins where it has a build (stable before uat).
     *
     * @return list<array{channel: string, platform: string, platform_label: string, arch: string, arch_label: string, version: string, size_bytes: int, sha256: string, min_os: ?string, signed: bool, released_at: string, url: string}>
     */
    public static function downloads(ReleaseChannel ...$channels): array
    {
        $downloads = [];
        $releases = self::query()
            ->whereIn('channel', $channels)
            ->where('active', true)
            ->orderByDesc('released_at')
            ->orderByDesc('id')
            ->get();

        foreach ($channels as $channel) {
            foreach ($releases->where('channel', $channel) as $release) {
                $downloads["{$release->platform->value}-{$release->arch}"] ??= $release->toDownload();
            }
        }

        return array_values($downloads);
    }

    /**
     * @return array{channel: string, platform: string, platform_label: string, arch: string, arch_label: string, version: string, size_bytes: int, sha256: string, min_os: ?string, signed: bool, released_at: string, url: string}
     */
    public function toDownload(): array
    {
        return [
            'channel' => $this->channel->value,
            'platform' => $this->platform->value,
            'platform_label' => $this->platform->label(),
            'arch' => $this->arch,
            'arch_label' => ReleasePlatform::archLabel($this->arch),
            'version' => $this->version,
            'size_bytes' => $this->size_bytes,
            'sha256' => $this->sha256,
            'min_os' => $this->min_os,
            'signed' => $this->signed,
            'released_at' => $this->released_at->toDateString(),
            'url' => $this->downloadUrl(),
        ];
    }

    /** A plain SprintSync address: no token, no file path. */
    public function downloadUrl(): string
    {
        return $this->channel === ReleaseChannel::Uat
            ? route('desktop.download.uat', ['platform' => $this->platform->value, 'arch' => $this->arch])
            : route('desktop.download', ['platform' => $this->platform->value, 'arch' => $this->arch]);
    }

    public function fileName(): string
    {
        return "SprintSync-{$this->version}-{$this->platform->value}-{$this->arch}.{$this->extension}";
    }
}
